(function(){
'use strict';
const $=id=>document.getElementById(id),themes=HomeThemes.THEMES.map(t=>({...t,period:NAOTOCCHI_THEME_ENGINE_V2.buildEvents(t.song,'piano').duration-1.2}));
const regions=[['home','おうち'],['forest','森'],['river_lake','水辺'],['city','都会'],['countryside','田舎'],['mountain','山'],['snow','雪国'],['sea','海'],['jungle','ジャングル'],['desert','砂漠'],['deepsea','深海'],['star_stop','星空'],['memory_lake','記憶の湖']];
const descriptions={original:'VERSION 1と同じ合成ピアノ・伴奏。比較用に再生音量だけをそろえています。',morning:{A:'柔らかなアップライトピアノを中心に、句末に小さなハープの光を。',B:'フルートの主旋律と、軽いハープの分散和音。朝の空気をふんわりと。'},day:{A:'いつもの伴奏を柔らかなピアノに。控えめなマリンバで、親しみやすさを残します。',B:'ピアノとマリンバ、弦のピッツィカート・ベース。小さな庭の弾むような温かさ。'},evening:{A:'ピアノの余韻を丸く整え、繊細なハープを添えた改良版。',B:'ピアノ、ハープ、薄い弦の重なり。主旋律を包む、少し切ない夕景。'},night:{A:'柔らかいピアノと控えめなハープ。静かな夜にも聴きやすい密度に。',B:'静かなピアノに、少量のベルと長い弦の響き。音の間を大切にしています。'}};
const originalExports=new Map();
let index=0,version='original',sequence=false,desired=false,request=0,notes={},storageOK=true;
try{notes=JSON.parse(localStorage.getItem('naotocchi-home-music-v2-notes')||'{}');if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={};}catch{storageOK=false;}
const key=()=>themes[index].id+':'+version,versionName=v=>v==='original'?'原曲':'アレンジ'+v;
function save(){notes[key()]={rating:$('rating').value,memo:$('memo').value,updatedAt:new Date().toISOString()};try{localStorage.setItem('naotocchi-home-music-v2-notes',JSON.stringify(notes));$('save-status').textContent='この端末に保存しました。';}catch{storageOK=false;$('save-status').textContent='端末に保存できません。下のボタンからJSONを保存してください。';}}
function loadNote(){const n=notes[key()]||{};$('rating').value=n.rating||'';$('memo').value=n.memo||'';$('save-status').textContent=storageOK?'評価とメモはこの端末に保存します。':'端末に保存できません。JSONで書き出せます。';}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const player=new ComparisonTransport({load:async(theme,ctx)=>{
 const fetchAudio=async v=>{const response=await fetch('audio/'+theme.id+'-'+v+'.m4a');if(!response.ok)throw Error('音源の読み込みに失敗しました。もう一度再生してください。');return ctx.decodeAudioData(await response.arrayBuffer());};
 const [original,A,B]=await Promise.all([NAOTOCCHI_THEME_ENGINE_V2.renderOffline(theme.song,'piano',{sampleRate:22050}),fetchAudio('A'),fetchAudio('B')]);originalExports.clear();originalExports.set(theme.id,original);return {original:loopBuffer(ctx,original,theme.period),A,B};
},onstatus:(state,item)=>{
 if(state==='loading')$('status').textContent='3つの音色を準備しています…';
 if(state==='playing'){$('now-title').textContent=item.theme.title+' · '+versionName(item.version);$('status').textContent=sequence?'朝→昼→夕→夜を連続再生中':'再生中 · 同じ位置で切り替えられます';$('level').textContent='音量補正後 '+(item.level.lufs+20*Math.log10(item.level.gain)).toFixed(1)+' LUFS · ゲイン補正のみ';}
 if(state==='ended'&&desired){if(sequence){if(index<3){index++;paint();start();}else if($('loop').checked){index=0;paint();start();}else stop('4曲の試聴が終わりました');}else stop('この曲の試聴が終わりました');}
}});
// Established iPhone media-session fallback, activated directly by the first tap.
let silent=null;function unlockMedia(){if(!silent){const n=4410,b=new Uint8Array(44+n*2),v=new DataView(b.buffer),w=(o,s)=>{for(let i=0;i<s.length;i++)b[o+i]=s.charCodeAt(i);};w(0,'RIFF');v.setUint32(4,36+n*2,true);w(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,44100,true);v.setUint32(28,88200,true);v.setUint16(32,2,true);v.setUint16(34,16,true);w(36,'data');v.setUint32(40,n*2,true);silent=document.createElement('audio');silent.setAttribute('playsinline','');silent.loop=true;silent.volume=.01;silent.src='data:audio/wav;base64,'+btoa(String.fromCharCode(...b));}silent.play()?.catch(()=>{});}
async function start(preserve=false){unlockMedia();desired=true;const token=++request;try{await player.play(themes[index],version,{preserve,loop:!sequence&&$('loop').checked});}catch(e){if(token!==request)return;stop(e.message||'再生できませんでした。再生ボタンで再開してください。');}}
function stop(message='停止しました'){request++;desired=false;player.stop();silent?.pause();$('status').textContent=message;$('now-title').textContent='停止中';$('elapsed').textContent='0:00';$('progress').style.width='0%';}
function scene(){try{$('home').contentWindow.HomeAuditionFixture?.setScene($('region').value,themes[index].slot);}catch{}}
function paint(){const t=themes[index];$('quick-time').value=String(index);$('quick-version').value=version;$('quick-region').value=$('region').value;for(const b of $('themes').children)b.setAttribute('aria-pressed',String(Number(b.dataset.index)===index));for(const b of $('versions').children)b.setAttribute('aria-pressed',String(b.dataset.version===version));$('arrangement').textContent=version==='original'?descriptions.original:descriptions[t.slot][version];$('scene-label').textContent=regions.find(r=>r[0]===$('region').value)[1]+' · '+t.label;scene();loadNote();const stem=t.id+'-'+version;$('downloads').innerHTML=version==='original'?'<a href="midi/'+stem+'.mid" download>原曲の比較用MIDI</a><button id="export-original">原曲WAVを保存</button>':'<a href="audio/'+stem+'.m4a" download>AAC音源</a><a href="audio/'+stem+'.flac" download>ロスレス原盤</a><a href="midi/'+stem+'.mid" download>MIDI</a>';if(version==='original')$('export-original').onclick=exportOriginal;}
async function exportOriginal(){const selected=themes[index];try{unlockMedia();await player.unlock();$('status').textContent='原曲WAVを準備しています…';const b=originalExports.get(selected.id)||await NAOTOCCHI_THEME_ENGINE_V2.renderOffline(selected.song,'piano',{sampleRate:22050}),n=b.length,data=new ArrayBuffer(44+n*2),v=new DataView(data),w=(o,s)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i));};w(0,'RIFF');v.setUint32(4,36+n*2,true);w(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,b.sampleRate,true);v.setUint32(28,b.sampleRate*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);w(36,'data');v.setUint32(40,n*2,true);const samples=b.getChannelData(0);for(let i=0;i<n;i++)v.setInt16(44+i*2,Math.max(-32768,Math.min(32767,samples[i]*32767)),true);download(new Blob([data],{type:'audio/wav'}),selected.id+'-original.wav');$('status').textContent='音量補正前の原曲WAVを書き出しました。';}catch(e){$('status').textContent=e.message;}}
for(const [i,t] of themes.entries()){const b=document.createElement('button');b.className='theme';b.dataset.index=i;b.innerHTML='<span class="slot">'+t.label+'　'+t.hours+'</span><b>'+t.title+'</b>';b.onclick=()=>{index=i;sequence=false;paint();if(desired)start();};$('themes').appendChild(b);const o=document.createElement('option');o.value=String(i);o.textContent=t.label+' · '+t.title;$('quick-time').appendChild(o);}
for(const [id,label] of regions){const o=document.createElement('option');o.value=id;o.textContent=label;$('region').appendChild(o);$('quick-region').appendChild(o.cloneNode(true));}
for(const b of $('versions').children)b.onclick=()=>{version=b.dataset.version;paint();if(desired)start(true);};
$('quick-time').onchange=()=>{index=Number($('quick-time').value);sequence=false;paint();if(desired)start();};$('quick-version').onchange=()=>{version=$('quick-version').value;paint();if(desired)start(true);};$('quick-region').onchange=()=>{$('region').value=$('quick-region').value;paint();};$('quick-play').onclick=()=>desired?stop():start();
$('region').onchange=scene;$('region').addEventListener('change',paint);$('home').onload=scene;window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('home').contentWindow&&e.data==='home-audition-ready')scene();});
$('reset-home').onclick=()=>{$('home').src='../../home-audition.html';};$('play').onclick=()=>start();$('stop').onclick=()=>stop();$('sequence').onclick=()=>{sequence=true;index=0;paint();start();};$('loop').onchange=()=>{if(desired&&!sequence)start(true);};$('volume').oninput=()=>{player.setVolume($('volume').value/100);$('volume-value').textContent=$('volume').value+'%';};$('rating').onchange=save;$('memo').oninput=save;$('export-notes').onclick=()=>download(new Blob([JSON.stringify({version:2,exportedAt:new Date().toISOString(),notes},null,2)],{type:'application/json'}),'naotocchi-music-v2-notes.json');
const fmt=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');setInterval(()=>{$('quick-play').textContent=desired?'■':'▶';$('quick-play').setAttribute('aria-label',desired?'音楽を停止':'音楽を再生');if(!player.playing)return;const p=player.position();$('elapsed').textContent=fmt(p.seconds)+' / '+fmt(p.duration);$('progress').style.width=(p.seconds/p.duration*100)+'%';if(sequence&&p.duration-p.seconds<8)player.prepare(themes[(index+1)%4]).catch(()=>{});},250);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&desired)stop('画面を離れたため停止しました。再生ボタンで再開できます。');});window.addEventListener('pagehide',()=>player.stop());paint();
})();
